import{z as l,x as o,o as e,c as s,q as t,j as B,D as E,d as i,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"成交模拟的深化","description":"","frontmatter":{"title":"成交模拟的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-fill-simulation-deep.md","filePath":"quant/bf-fill-simulation-deep.md","lastUpdated":1791063341000}'),d={name:"quant/bf-fill-simulation-deep.md"};function p(u,a,h,m,c,f){const r=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="成交模拟的深化" tabindex="-1">成交模拟的深化 <a class="header-anchor" href="#成交模拟的深化" aria-label="Permalink to &quot;成交模拟的深化&quot;">​</a></h1><div class="epigraph"><p>成交模拟器站在回测保真度的顶上：它住在哪一档，滑点与容量的结论就只能住在哪一档。</p><footer>—— 据 Harris, Trading and Exchanges, 2003 对优先规则与成交机制的论述；对照 Hasbrouck, Empirical Market Microstructure, 2007 整理</footer></div><p><a href="/quant/bf-vectorized-vs-event">上一课</a>把粗筛与定案分了层，定案的可信度全部落在撮合模拟器上。<a href="/quant/event-driven-backtest">事件驱动回测引擎</a>给过三档粗分——中点加价差、价位队列、订单日志回放——本课把档位拆开写：每档能回答什么、不能回答什么、怎么校准、怎么防止它高估你。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成交模拟器决定「你的单子以什么价、多少量、在哪个事件上成交」。乐观偏差在这里进入系统，且几乎总是乐观：假设限价单一到就排队头，忽略自己的单子对簿的消耗，忽略跨越更优价的成交必须先吃掉那些价（trade-through），把决策到下单的延迟设为零。每一种都把滑点算小、把夏普算大，而且方向一致——<a href="/quant/simulator-impact-bias">模拟器偏差</a>课指出，训练或评估环境的乐观误差不会被对冲掉。部分成交同样：剩余量挂在簿上是风险也是信息，<a href="/quant/order-state-machine">订单状态机</a>要求它成为一等状态，模拟器必须更新它而不是假装一次成交完成。</p><h3 id="档位阶梯" tabindex="-1">档位阶梯 <a class="header-anchor" href="#档位阶梯" aria-label="Permalink to &quot;档位阶梯&quot;">​</a></h3><p>第一档：下一笔成交价或中点加价差，无条件成交。只回答方向经济学，适用于日频定案前的粗估。第二档：顶层队列消耗——你的单子挂在某价位，按历史成交打印逐笔消耗队首数量；你的到队位置是未知量，通常保守假设排在同价现有单之后，用<a href="/quant/fill-probability">排队与成交概率</a>模型补充。第三档：L2 深度消耗——沿价位图吃深度，但<a href="/quant/l2-l3-data">Level-2 / Level-3 数据</a>已经说明聚合档位丢失了档内次序，此档回答不了队列名次。第四档：订单日志回放，带订单号重建真实队列，保真度最高，见<a href="/quant/orderbook-reconstruction">订单簿重建</a>，代价是数据与算力。</p>',7)),(e(),B(A,null,{default:E(()=>[n(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E8%AE%A2%E5%8D%95%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20TIER%7B%22%E6%A1%A3%E4%BD%8D%E5%A3%B0%E6%98%8E%22%7D%0A%20%20TIER%20--%3E%7C%E4%B8%80%7C%20NP%5B%22%E4%B8%AD%E7%82%B9%E6%88%96%E4%B8%8B%E4%B8%80%E4%BB%B7%20%E6%97%A0%E6%9D%A1%E4%BB%B6%E6%88%90%E4%BA%A4%22%5D%0A%20%20TIER%20--%3E%7C%E4%BA%8C%7C%20TQ%5B%22%E9%A1%B6%E5%B1%82%E9%98%9F%E5%88%97%E6%8C%89%E6%89%93%E5%8D%B0%E6%B6%88%E8%80%97%22%5D%0A%20%20TIER%20--%3E%7C%E4%B8%89%7C%20L2%5B%22L2%20%E6%B7%B1%E5%BA%A6%E6%B6%88%E8%80%97%22%5D%0A%20%20TIER%20--%3E%7C%E5%9B%9B%7C%20L3%5B%22%E8%AE%A2%E5%8D%95%E6%97%A5%E5%BF%97%E9%87%8D%E5%BB%BA%E9%98%9F%E5%88%97%22%5D%0A%20%20NP%20--%3E%20ST%5B%22%E5%9B%9E%E6%8A%A5%E8%BF%9B%E8%AE%A2%E5%8D%95%E7%8A%B6%E6%80%81%E6%9C%BA%20%E6%9B%B4%E6%96%B0%E5%89%A9%E4%BD%99%E9%87%8F%22%5D%0A%20%20TQ%20--%3E%20ST%0A%20%20L2%20--%3E%20ST%0A%20%20L3%20--%3E%20ST%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">术语翻译：L1 是「成交了什么」（价格与量），L2 是「想成交可以挂哪」（聚合后的各价位深度），L3 是「谁先谁后」（每笔挂单的完整队列）。档位越高越接近交易所真实看到的簿，但数据量也从每兆涨到每吉——保真度是拿存储和算力买来的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>档位必须随结果一起声明，因为<a href="/quant/capacity-participation">容量</a>与滑点敏感性都依赖它。三件事跨档位通用。其一，延迟显式化：订单请求在 \\(k\\) 个事件之后才对撮合器可见，\\(k\\) 声明为情景而不是常数零。其二，费用结构：maker-taker 返佣与印花税按场所分支，见<a href="/quant/maker-taker">Maker-taker 费用</a>；同一策略换场所，最优挂撤行为反转。其三，种子化：队列消耗里凡有随机模型（如到队位置的先验），必须可种子化，同一 seeds 重放必得同一回报，否则上一课的对拍协议无从执行。</p><p>校准的对照物不是回测自己，而是实盘交易分析：到达价、有效价差、完成率——<a href="/quant/slippage-attribution">滑点归因</a>的分解逐项对上模拟器的对应参数。对不上时修参数，不修信号。</p><p><span class="marginnote">限价成交是条件事件：价格走到你，往往因为有人带着你不知道的消息来。队列模型若只算成交概率、不联带逆向选择，会把最容易成交的时刻恰恰当作利润来源——这是成交模拟最深的结构性乐观。</span></p><p><span class="marginnote">数字实例：0.03% 的费率差就足以反转挂撤选择。taker 单在价差 0.05% 的市场吃单，成本约 \\(0.05\\%+0.03\\%=0.08\\%\\)；maker 挂队首等成交，若返佣 0.02%，期望成本约 \\(0.025\\%-0.02\\%\\approx 0.005\\%\\)——但要承担不成交与逆向选择。费用表改一栏，策略的挂撤逻辑就得重新校准。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>档位阶梯的本质是信息集的阶梯：第一档只用价格序列，第二档加成交打印，第三档加价位深度，第四档加订单全序。保真度不随档位平滑上升：第二档在薄队列上会系统性地高估成交，因为真实队列里有你看不见的隐藏量与提前撤单；第三档的聚合深度反而可能比诚实的第二档更误导。因此档位选择是「问题需要什么」决定，不是「数据有什么」决定——回答排队位置的问题，第三档是假装，要么上第四档，要么把统计模型写成显式情景。</p><p>乐观偏差从哪几个口进入结论：</p>',9)),(e(),B(A,null,{default:E(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%3A%20%E6%BB%91%E7%82%B9%E4%B8%BA%E4%BB%80%E4%B9%88%E6%80%BB%E6%98%AF%E8%A2%AB%E4%BD%8E%E4%BC%B0%3F%22%5D%20--%3E%20S1%5B%22%E6%8E%92%E9%98%9F%E4%BD%8D%E7%BD%AE%3A%20%E5%81%87%E8%AE%BE%E4%B8%80%E5%88%B0%E5%B0%B1%E6%8E%92%E5%A4%B4%22%5D%0A%20%20Q%20--%3E%20S2%5B%22%E9%9A%90%E8%97%8F%E9%87%8F%E4%B8%8E%E6%92%A4%E5%8D%95%3A%20%E7%9C%8B%E4%B8%8D%E8%A7%81%E7%9A%84%E5%AF%B9%E6%89%8B%22%5D%0A%20%20Q%20--%3E%20S3%5B%22%E8%87%AA%E8%BA%AB%E5%86%B2%E5%87%BB%3A%20%E5%90%83%E6%8E%89%E8%87%AA%E5%B7%B1%E7%9A%84%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20S4%5B%22%E5%BB%B6%E8%BF%9F%3A%20%E5%86%B3%E7%AD%96%E5%88%B0%E4%B8%8B%E5%8D%95%E4%B8%8D%E6%98%AF%E9%9B%B6%22%5D%0A%20%20Q%20--%3E%20S5%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%3A%20%E4%BB%B7%E6%A0%BC%E8%B5%B0%E5%88%B0%E4%BD%A0%E6%97%B6%E5%B8%A6%E7%9D%80%E5%9D%8F%E6%B6%88%E6%81%AF%22%5D%0A%20%20S1%20--%3E%20E%5B%22%E6%AF%8F%E4%B8%80%E9%A1%B9%E9%83%BD%E6%8A%8A%E6%BB%91%E7%82%B9%E7%AE%97%E5%B0%8F%22%5D%0A%20%20S2%20--%3E%20E%0A%20%20S3%20--%3E%20E%0A%20%20S4%20--%3E%20E%0A%20%20S5%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22%E5%A4%8F%E6%99%AE%E8%99%9A%E9%AB%98%2C%20%E6%96%B9%E5%90%91%E4%B8%80%E8%87%B4%2C%20%E5%AF%B9%E5%86%B2%E4%B8%8D%E6%8E%89%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>集合竞价、涨跌停与停牌各有自己的撮合语义，不能塞进连续档位，见<a href="/quant/halt-limit-backtest">停牌与涨跌停对回测</a>；真实交易所的优先规则参考<a href="/quant/matching-engine-arch">撮合引擎架构</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模拟器不能比数据更真：只有 L2 就声明队列模型是猜测，写成情景做敏感性，而不是当成交易所真相。不要把模拟器调到与某段实盘完全吻合——那是对单一路径过拟合，<a href="/quant/simulator-impact-bias">模拟器偏差</a>的警告适用于一切评估环境。保守默认值（到队排尾、延迟非零、成交概率打折）是 Pardo 的老建议：默认值不自动保守，必须有人在验收时签字。</p><p><span class="marginnote">常见误区：初学者容易以为「模拟器对上某段实盘滑点=校准完成」。对单一路径的精确吻合往往是对那一天的过拟合——市场只走了一种走法。合格的校准是分项对上：到达价、有效价差、完成率各自接近，且换一段行情不崩，而不是让总滑点凑等。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成交模拟器四档：中点、顶层队列、L2 深度、订单日志回放；档位决定滑点与容量结论的上限，必须声明。</li><li>延迟、费用、种子跨档位通用：延迟是情景，费用按场所，随机必须可重放。</li><li>乐观偏差是结构性的：排队位置、隐藏量、自身冲击、逆向选择，默认全都在高估你。</li><li>校准对照实盘 TCA，逐项归因；对单段实盘的精确吻合是过拟合不是校准。</li><li>出处：Harris, <em>Trading and Exchanges</em>, 2003；Hasbrouck, <em>Empirical Market Microstructure</em>, 2007；Pardo, <em>The Evaluation and Optimization of Trading Strategies</em>, 2007；站内<a href="/quant/order-state-machine">订单状态机</a>、<a href="/quant/l2-l3-data">Level-2 / Level-3 数据</a>各课。</li></ul>',6))])}const T=l(d,[["render",p]]);export{_ as __pageData,T as default};
